sn_aia_tool.script:
(function(inputs) {
    try{
        var userGr = new GlideRecordSecure('x_aleen_snguardian_identity');
        userGr.addQuery('email', inputs.user_email);
        userGr.query();
        if (userGr.next()) {
            var idenLocationGr = new GlideRecordSecure('x_aleen_snguardian_identity_location');
            idenLocationGr.addQuery('identity', userGr.getValue('sys_id'));
            idenLocationGr.query();
            if(idenLocationGr.next()){
                return JSON.stringify({
                    "identityId": userGr.getValue('sys_id'),
                    "location": idenLocationGr.getValue('location'),
                    "location_name": idenLocationGr.getDisplayValue('location')
                });
            }else{
                return JSON.stringify({
                "success": false,
                "identityId": userGr.getValue('sys_id'),
                "message": "User Location not found"
            });
            }
        } else {
            return JSON.stringify({
                "success": false,
                "message": "User not found"
            });
        }
    }catch(err){
        gs.info("Eror in Fetching identity: "+err.message);
    }
})(inputs);
